package tech.lightclient.commands.commands.defaults;import tech.lightclient.LightClient;import tech.lightclient.client.utils.player.PlayerUtils;import tech.lightclient.commands.Command;import tech.lightclient.commands.argument.IArgConsumer;import tech.lightclient.commands.datatypes.KeyDataType;import tech.lightclient.commands.exception.CommandException;import tech.lightclient.modules.api.Function;import tech.lightclient.modules.api.FunctionManager;import tech.lightclient.modules.api.settings.api.Setting;import tech.lightclient.modules.api.settings.impl.BooleanSetting;import lombok.AccessLevel;import lombok.experimental.FieldDefaults;import net.minecraft.util.Formatting;import org.lwjgl.glfw.GLFW;import java.util.Arrays;import java.util.Comparator;import java.util.List;import java.util.Locale;import java.util.stream.Stream;@FieldDefaults(level = AccessLevel.PRIVATE, makeFinal = true)public class BindCommand extends Command {    FunctionManager functionManager;    public BindCommand() {        super("bind");        functionManager = LightClient.getFunctionManager();    }    @Override    public void execute(String label, IArgConsumer args) throws CommandException {        String action = args.hasAny() ? args.getString().toLowerCase(Locale.US) : "list";        System.out.println("пырив");        switch (action) {            case "add":                handleAddBind(args);                break;            case "remove":                handleRemoveBind(args);                break;            case "list":                handleListBinds(args, label);                break;            case "clear":                handleClearBinds(args);                break;        }    }    void handleAddBind(IArgConsumer args) throws CommandException {        args.requireExactly(2);        String functionName = args.getString();        int key = args.getDatatypeFor(KeyDataType.INSTANCE).getValue();        Function function = functionManager.getFunctionByName(functionName);        if (function == null) {            logDirect("В§cФункция В§f" + functionName + "В§c не найдена!");            return;        }        functionManager.getVisibleFunctions().stream()                .filter(f -> f.getBind() == key && f != function)                .findFirst()                .ifPresent(existing -> logDirect(Formatting.YELLOW + "Клавиша В§b" +                        PlayerUtils.getBindName(key) + Formatting.YELLOW +                        " уже занята функцией В§c" + existing.getName()));        function.setBind(key);        logDirect(Formatting.GREEN + "Функция В§f" + function.getName() +                Formatting.GREEN + " успешно привязана Рє В§f" + PlayerUtils.getBindName(key));    }    void handleRemoveBind(IArgConsumer args) throws CommandException {        args.requireExactly(1);        String functionName = args.getString();        Function function = functionManager.getFunctionByName(functionName);        if (function == null) {            logDirect("В§cФункция В§f" + functionName + "В§c не найдена!");            return;        }        if (function.getBind() == GLFW.GLFW_KEY_UNKNOWN || function.getBind() == GLFW.GLFW_MOUSE_BUTTON_1) {            logDirect("В§eРЈ функции В§f" + function.getName() + "В§e нет привязанной клавиши.");            return;        }        String keyName = PlayerUtils.getBindName(function.getBind());        function.setBind(GLFW.GLFW_KEY_UNKNOWN);        logDirect("В§aБинд В§f" + function.getName() + " В§8(В§c" + keyName + "В§8) В§aуспешно удалён.");    }    void handleListBinds(IArgConsumer args, String label) throws CommandException {        args.requireMax(0);        List<Function> boundFunctions = functionManager.getVisibleFunctions().stream()                .filter(f -> {                    int bind = f.getBind();                    return bind != GLFW.GLFW_KEY_UNKNOWN                            && bind != -1                            && bind != GLFW.GLFW_MOUSE_BUTTON_1;                })                .sorted(Comparator.comparing(f -> f.getName().toLowerCase(Locale.US)))                .toList();        int booleanBindCount = 0;        for (Function f : functionManager.getVisibleFunctions()) {            for (Setting<?> s : f.getSettings()) {                if (s instanceof BooleanSetting bs && bs.isBound()) {                    booleanBindCount++;                }            }        }        if (boundFunctions.isEmpty() && booleanBindCount == 0) {            logDirect("В§fНет привязанных функций. РСЃРїРѕР»СЊР·СѓР№ В§a.bind add <функция> <клавиша>");            return;        }        logDirect("В§fПривязанные функции:");        for (Function func : boundFunctions) {            String keyName = PlayerUtils.getBindName(func.getBind());            logDirect(" В§7вЂў В§f" + func.getName() + " В§8в†’ В§c" + keyName);        }        if (booleanBindCount > 0) {            logDirect("В§fПривязанные настройки:");            for (Function f : functionManager.getVisibleFunctions()) {                for (Setting<?> s : f.getSettings()) {                    if (s instanceof BooleanSetting bs && bs.isBound()) {                        String keyName = PlayerUtils.getBindName(bs.getBind());                        logDirect(" В§7вЂў В§f" + f.getName() + ": " + bs.getName() + " В§8в†’ В§c" + keyName);                    }                }            }        }        logDirect("В§8Страница В§71В§8/В§71");    }    void handleClearBinds(IArgConsumer args) throws CommandException {        args.requireMax(0);        int cleared = 0;        for (Function f : functionManager.getFunctions()) {            if (f.getBind() != GLFW.GLFW_KEY_UNKNOWN) {                f.setBind(GLFW.GLFW_KEY_UNKNOWN);                cleared++;            }        }        for (Function f : functionManager.getFunctions()) {            for (Setting<?> s : f.getSettings()) {                if (s instanceof BooleanSetting bs && bs.isBound()) {                    bs.setBind(-1);                    cleared++;                }            }        }        logDirect(Formatting.GREEN + "Успешно удалено биндов: " + cleared);    }    @Override    public Stream<String> tabComplete(String label, IArgConsumer args) throws CommandException {        if (args.hasExactlyOne()) {            String prefix = args.peekString(0).toLowerCase(Locale.US);            return Stream.of("add", "remove", "list", "clear")                    .filter(s -> s.startsWith(prefix))                    .sorted();        }        String action = args.peekString(0).toLowerCase(Locale.US);        if ("add".equals(action)) {            if (args.hasExactly(2)) {                String prefix = args.peekString(1).toLowerCase(Locale.US);                return functionManager.getVisibleFunctions().stream()                        .map(Function::getName)                        .filter(name -> name.startsWith(prefix))                        .sorted(String.CASE_INSENSITIVE_ORDER);            }            if (args.hasExactly(3)) {                return args.tabCompleteDatatype(KeyDataType.INSTANCE);            }        }        if ("remove".equals(action) && args.hasExactly(2)) {            String prefix = args.peekString(1).toLowerCase(Locale.US);            return functionManager.getVisibleFunctions().stream()                    .filter(f -> {                        int bind = f.getBind();                        return bind != GLFW.GLFW_KEY_UNKNOWN                                && bind != -1                                && bind != GLFW.GLFW_MOUSE_BUTTON_1;                    })                    .map(Function::getName)                    .map(String::toLowerCase)                    .filter(name -> name.startsWith(prefix))                    .map(name -> name.substring(0, 1).toUpperCase() + name.substring(1))                    .sorted(String.CASE_INSENSITIVE_ORDER);        }        return Stream.empty();    }    @Override    public String getShortDesc() {        return "Управление биндами для модулей.";    }    @Override    public List<String> getLongDesc() {        return Arrays.asList(                "Эта команда позволяет управлять биндами для модулей, которые будут активироваться при нажатии определённых клавиш.",                "",                "РСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ:",                "> bind add <module> <key> - Привязывает модуль Рє указанной клавише.",                "> bind remove <module> - Удаляет привязку модуля.",                "> bind list - Показывает список всех текущих биндов модулей.",                "> bind clear - Удаляет все бинды модулей."        );    }}